import Foundation

/// A row of `route_headsigns.txt`: the most common GTFS `trip_headsign` for a route and direction.
/// Generated by `scripts/make_route_headsigns.py`.
struct MTABusRouteHeadsign: Codable, Hashable {
    var routeId: String
    var directionId: String
    var headsign: String

    enum CodingKeys: Int, CodingKey {
        case routeId = 0
        case directionId = 1
        case headsign = 2
    }

    static func key(routeId: String, directionId: String) -> String {
        "\(routeId)|\(directionId)"
    }

    var key: String {
        MTABusRouteHeadsign.key(routeId: routeId, directionId: directionId)
    }
}
